    c = ("The notifications captured students' attention, so students could not attend selectively to the lecture (selective attention), which meant that less of the lecture was encoded into memory and quiz scores were lower.",
         _expl_rows("C", ["Applies a psychological perspective, theory, concept, or research finding from the course, such as selective attention, divided attention, encoding, the cocktail party effect, the multi-store model, or the working memory model, to explain how the evidence supports the claim"], ["selective attention was disrupted by the notification sounds", "less information was encoded into long-term memory because attention was divided", "the working memory model: the central executive was pulled away from the lecture"], ["explains how the evidence supports the claim: the evidence shows learning decreased when phones were present, which supports banning them", "links the evidence to the claim by reasoning about the results"], ["the results show students learned less, which supports the claim"]))
    d = ("Source 2: 58 percent of students said that they check their phones at least five times in a typical class.",
         [_ev("D1", "Uses one specific, accurate, and correctly cited piece of evidence from a different source than part B", ["Cites a different source from the one used in part B and gives specific and relevant evidence from it that supports the claim"], ["Source 2: 71% of teachers say phones distract students", "Source 3: schools with bans had mean math scores 2 points higher", "Source 1: 78% versus 66% (if Source 2 or 3 was used in part B)"], ["uses the same source as part B", "gives evidence with no citation", "gives evidence that is not relevant to the claim"])])
    e = ("Frequent checking is reinforced on a variable-ratio schedule: unpredictable notifications and messages reward checking, which makes the behavior persistent and hard to stop, so students are repeatedly distracted during class.",
         _expl_rows("E", ["Applies a different psychological perspective, theory, concept, or research finding from the course than the one used in part C, such as operant conditioning with a variable-ratio schedule, positive reinforcement, emotion-focused coping, negative reinforcement, social comparison, or habituation"], ["variable-ratio reinforcement: unpredictable messages keep students checking", "negative reinforcement: checking the phone reduces anxiety, so the behavior increases", "emotion-focused coping: students use phones to manage anxious feelings, which is why some students oppose a ban"], ["explains how the evidence supports the claim: frequent checking shows how often attention leaves the lesson", "links the survey percentages to the claim"], ["students check their phones often, so a ban helps"]))
    return _mk_frq("psf_ebq_phones", "ebq", "2.1", ["2.4", "3.8", "5.1"], "4.B", "Phones in class", intro, stim, _ebq_parts(q, ["2.1", "3.8"], claim, b, c, d, e), 45,
                   "Evidence-Based Question: propose a claim, support it with evidence from two sources, and explain with two different concepts", ["Propose a specific claim", "Cite specific evidence from one source and explain it with a course concept", "Cite evidence from a different source and explain it with a different concept"],
                   [("each source reports specific numbers or results that can be cited", "source text and table")], PATH_FRQ)


