def psf_ebq_spacing(rng):
    q = "Should teachers organize homework and review so that learning is spread out over time instead of concentrated just before a test?"
    intro = _sources([
        ("A laboratory experiment", "Researchers randomly assigned 100 adults to learn 60 unfamiliar foreign words in one of two ways. The Massed group (50 adults) studied the words in one 60-minute session. The Spaced group (50 adults) studied for 20 minutes on each of three days. All participants were tested on the words one week later. The mean number of words recalled was 21 in the Massed group and 33 in the Spaced group. The difference was statistically significant."),
        ("A classroom study of weekly quizzes", "In one school district, 12 history classes were randomly selected to give a short cumulative quiz each week (Quiz classes), and 12 classes used no weekly quizzes (No-quiz classes). The same teacher taught one Quiz class and one No-quiz class, and all classes took the same final exam. The mean final exam score was 84 percent in the Quiz classes and 78 percent in the No-quiz classes. The researchers reported that the difference was statistically significant."),
        ("A survey of study habits", "Researchers surveyed 500 high school students. Of the students, 70 percent said that studying a lot the night before a test works better than studying a little each day. When the researchers compared the students' reported study methods with their exam grades, they found that students who reported studying a little each day earned higher grades on average than students who reported cramming. Students who volunteered for the survey were more likely to be in advanced classes."),
    ])
    stim = tbl("Summary of the key results in the three sources", ["Source", "Type of study", "Key result"], [["1", "Experiment (100 adults)", "Mean words recalled: 21 (Massed) vs 33 (Spaced); statistically significant"], ["2", "Classroom experiment (24 classes)", "Mean final exam: 84% (weekly quizzes) vs 78% (no quizzes); statistically significant"], ["3", "Survey of 500 students", "70% believe cramming works better; students who studied a little each day earned higher grades on average"]])
    claim = ["Teachers should spread homework and review across the weeks before a test, because spaced learning produces better recall than cramming.", "Teachers should use weekly cumulative quizzes and spaced review because they raise exam scores.", "Teachers should teach students that spaced study is more effective than cramming even though many students believe the opposite."]
    b = ("Source 1: the Spaced group recalled a mean of 33 words, compared with 21 words for the Massed group.",
         [_ev("B1", "Uses one specific, accurate, and correctly cited piece of evidence from one source", ["Cites one source (Source 1, 2, or 3) and gives specific and relevant evidence from it that supports the student's claim"], ["Source 1: 33 words versus 21 words", "Source 2: 84% versus 78% on the final exam", "Source 3: 70% of students believe cramming works better"], ["gives evidence with no citation", "gives a vague statement such as 'studies show spacing works'", "gives evidence that is not relevant to the claim"])])
    c = ("The spacing effect: information that is encoded over time through distributed practice is better consolidated and remembered than information encoded all at once through massed practice.",
         _expl_rows("C", ["Applies a psychological perspective, theory, concept, or research finding from the course, such as the spacing effect, distributed practice versus massed practice, memory consolidation, or encoding, to explain how the evidence supports the claim"], ["the spacing effect", "distributed practice produces stronger encoding than massed practice", "memory consolidation occurs between study sessions", "the testing effect or retrieval practice (if the quiz evidence is used here)", "metacognition: students misjudge which study method works"], ["explains how the evidence supports the claim: the spaced group recalled more words, which supports spreading out learning", "links the difference in words recalled to the claim"], ["the spaced group learned more, so spacing is better"]))
    d = ("Source 2: classes that gave weekly cumulative quizzes had a mean final exam score of 84 percent, compared with 78 percent in classes that gave no weekly quizzes.",
         [_ev("D1", "Uses one specific, accurate, and correctly cited piece of evidence from a different source than part B", ["Cites a different source from the one used in part B and gives specific and relevant evidence from it that supports the claim"], ["Source 2: 84% versus 78% final exam", "Source 3: students who studied a little each day earned higher grades on average", "Source 1: 33 versus 21 words (if Source 2 or 3 was used in part B)"], ["uses the same source as part B", "gives evidence with no citation", "gives evidence that is not relevant to the claim"])])
    e = ("Weekly quizzes require students to retrieve information, and retrieval practice (the testing effect) makes later successful retrieval more likely than rereading alone, so quizzes spread across weeks raise exam scores.",
         _expl_rows("E", ["Applies a different psychological perspective, theory, concept, or research finding from the course than the one used in part C, such as the testing effect and retrieval practice, metacognition, retrieval cues, or elaborative rehearsal, to explain how the evidence supports the claim"], ["the testing effect: practicing retrieval strengthens memory", "retrieval practice during quizzes made later retrieval easier", "metacognition: quizzes show students what they do not know yet", "the spacing effect or distributed practice (if the evidence from the spacing experiment is used here)"], ["explains how the evidence supports the claim: classes with quizzes scored higher, which supports using frequent review", "links the exam score difference to the claim"], ["quizzes help students, so teachers should use them"]))
    return _mk_frq("psf_ebq_spacing", "ebq", "2.4", ["2.6", "2.7"], "4.B", "Spaced learning", intro, stim, _ebq_parts(q, ["2.4", "2.6"], claim, b, c, d, e), 45,
                   "Evidence-Based Question: propose a claim, support it with evidence from two sources, and explain with two different concepts", ["Propose a specific claim", "Cite specific evidence from one source and explain it with a course concept", "Cite evidence from a different source and explain it with a different concept"],
                   [("each source reports specific numbers or results that can be cited", "source text and table")], PATH_FRQ)


