def psf_ebq_team_bonus(rng):
    q = "Should a company reward employees mainly with team-based bonuses instead of individual bonuses?"
    intro = _sources([
        ("A laboratory experiment on effort", "Researchers asked 80 students to pull on a rope-pulling machine that measured force. In the Alone condition (40 students), each student believed that his or her own force was measured. In the Team condition (40 students), each student believed that only the total force of a four-person team was measured. Students in the Alone condition produced a mean force of 100 units, and students in the Team condition produced a mean force of 78 units. The difference was statistically significant."),
        ("A survey of employee burnout", "Researchers surveyed 500 employees at a large company about their workload and their sense of burnout. Employees who said that the amount of work in their team was shared unfairly reported more burnout, and the correlation between perceived unfairness of workload and burnout was r = +0.44. Employees who volunteered to answer the survey were more likely to work in teams that rewarded group results."),
        ("A field study of two sales offices", "Researchers compared two sales offices of the same company for one year. Office A paid a bonus based on each salesperson's own sales (individual bonus), and Office B paid a bonus based on the sales of the entire office (team bonus). Office A's mean monthly sales per person were $52,000 and Office B's were $47,000. Employees were not randomly assigned to the offices, and Office B was in a region with lower average incomes."),
    ])
    stim = tbl("Summary of the key results in the three sources", ["Source", "Type of study", "Key result"], [["1", "Experiment (80 students)", "Mean force: 100 units (Alone) vs 78 units (Team); statistically significant"], ["2", "Survey (500 employees)", "r = +0.44 between perceived unfair workload and burnout"], ["3", "Field comparison of two offices", "Mean monthly sales per person: $52,000 (individual bonus) vs $47,000 (team bonus); employees not randomly assigned"]])
    claim = ["A company should not rely mainly on team-based bonuses, because people put in less effort when their individual contribution cannot be identified.", "A company should combine individual and team rewards, because team bonuses alone reduce effort and unfair workloads are linked to burnout.", "A company should reward individuals for their own contributions while encouraging teamwork."]
    b = ("Source 1: students in the Team condition produced a mean force of 78 units, compared with 100 units for students in the Alone condition.",
         [_ev("B1", "Uses one specific, accurate, and correctly cited piece of evidence from one source", ["Cites one source (Source 1, 2, or 3) and gives specific and relevant evidence from it that supports the student's claim"], ["Source 1: 78 units versus 100 units of force", "Source 2: r = +0.44 between unfair workload and burnout", "Source 3: $52,000 versus $47,000 in monthly sales"], ["gives evidence with no citation", "gives a vague statement such as 'people work less in groups'", "gives evidence that is not relevant to the claim"])])
    c = ("Social loafing: people tend to put in less effort when working in a group because their individual effort is not identifiable, which is why the Team condition produced less force.",
         _expl_rows("C", ["Applies a psychological perspective, theory, concept, or research finding from the course, such as social loafing, diffusion of responsibility, or social facilitation, to explain how the evidence supports the claim"], ["social loafing", "diffusion of responsibility: each person feels less responsible in a team", "individual effort was not identifiable in the team condition"], ["explains how the evidence supports the claim: effort was lower when only team performance was measured, which supports not relying on team bonuses", "links the difference in force to the claim"], ["people worked less in the team, so team bonuses are bad"]))
    d = ("Source 2: employees who said the workload in their team was shared unfairly reported more burnout, with a correlation of r = +0.44.",
         [_ev("D1", "Uses one specific, accurate, and correctly cited piece of evidence from a different source than part B", ["Cites a different source from the one used in part B and gives specific and relevant evidence from it that supports the claim"], ["Source 3: $52,000 versus $47,000", "Source 2: r = +0.44 between unfair workload and burnout", "Source 1: 78 versus 100 units (if Source 2 or 3 was used in part B)"], ["uses the same source as part B", "gives evidence with no citation", "gives evidence that is not relevant to the claim"])])
    e = ("Burnout is a work-related stress response (distress) that can build when team rewards leave some members carrying more of the load; fairer, individually tracked rewards reduce that source of stress, which supports not relying mainly on team bonuses.",
         _expl_rows("E", ["Applies a different psychological perspective, theory, concept, or research finding from the course than the one used in part C, such as incentive theory, extrinsic motivation, positive reinforcement, burnout in industrial-organizational psychology, or distress, to explain how the evidence supports the claim"], ["incentive theory: rewards motivate behavior", "extrinsic motivation from the individual bonus", "burnout is a work-related stress response, so unfair workloads in teams can hurt employees"], ["explains how the evidence supports the claim: sales were higher in the office that tied the reward to individual results", "links the sales difference to the claim"], ["the individual bonus office sold more, so individual bonuses are better"]))
    return _mk_frq("psf_ebq_team_bonus", "ebq", "4.3", ["4.6", "5.1"], "4.B", "Team bonuses", intro, stim, _ebq_parts(q, ["4.3", "4.6"], claim, b, c, d, e), 45,
                   "Evidence-Based Question: propose a claim, support it with evidence from two sources, and explain with two different concepts", ["Propose a specific claim", "Cite specific evidence from one source and explain it with a course concept", "Cite evidence from a different source and explain it with a different concept"],
                   [("each source reports specific numbers or results that can be cited", "source text and table")], PATH_FRQ)


